import { useState } from "react";

export function Dropdown({
  label = "{{label}}",
  open: initialOpen = {{open}},
  placement = "{{placement}}",
  accent = "{{accent}}",
  width = {{width}},
}) {
  const [open, setOpen] = useState(initialOpen);
  const menuPos = placement === "above" ? { bottom: "calc(100% + 6px)" } : { top: "calc(100% + 6px)" };
  return (
    <div style={{ position: "relative", minHeight: 220, padding: "60px 24px", boxSizing: "border-box", fontFamily: "system-ui, sans-serif" }}>
      <style>{`.dropdown-react-item:hover, .dropdown-react-item:focus-visible { background: ${accent}; outline: none; }`}</style>
      <div style={{ position: "relative", display: "inline-block" }}>
        <button type="button" aria-haspopup="true" aria-expanded={open ? "true" : "false"} onClick={() => setOpen((o) => !o)}
          style={{ display: "inline-flex", alignItems: "center", gap: 8, background: "#FAF7F2", color: "#241430",
            border: "1.5px solid #24143033", borderRadius: 8, padding: "9px 14px", fontWeight: 500, cursor: "pointer" }}>
          {label}
          <svg width="10" height="6" viewBox="0 0 10 6" aria-hidden="true"><path d="M1 1l4 4 4-4" stroke="currentColor" strokeWidth="1.6" fill="none" strokeLinecap="round" strokeLinejoin="round"/></svg>
        </button>
        {open && (
          <ul role="menu" style={{ position: "absolute", left: 0, width, margin: 0, padding: 6, listStyle: "none",
            background: "#FAF7F2", borderRadius: 10, boxShadow: "0 16px 32px rgba(36,20,48,.22)", boxSizing: "border-box", ...menuPos }}>
            <li role="menuitem"><button type="button" className="dropdown-react-item" style={{ width: "100%", textAlign: "left", background: "none", border: "none", borderRadius: 6, padding: "8px 10px", font: "inherit", color: "#241430", cursor: "pointer" }}>Duplicate</button></li>
            <li role="menuitem"><button type="button" className="dropdown-react-item" style={{ width: "100%", textAlign: "left", background: "none", border: "none", borderRadius: 6, padding: "8px 10px", font: "inherit", color: "#241430", cursor: "pointer" }}>Rename</button></li>
            <li role="menuitem"><button type="button" className="dropdown-react-item" style={{ width: "100%", textAlign: "left", background: "none", border: "none", borderRadius: 6, padding: "8px 10px", font: "inherit", color: "#a6355c", cursor: "pointer" }}>Delete</button></li>
          </ul>
        )}
      </div>
    </div>
  );
}
